import{_ as r,l as n,o as a,c as i,v as t,p as l,x as s,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"Sv39 页表格式","description":"","frontmatter":{"title":"Sv39 页表格式","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sv39-page-table.md","filePath":"cs/sv39-page-table.md","lastUpdated":1789023840000}'),P={name:"cs/sv39-page-table.md"};function h(v,e,S,E,u,_){const o=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="sv39-页表格式" tabindex="-1">Sv39 页表格式 <a class="header-anchor" href="#sv39-页表格式" aria-label="Permalink to &quot;Sv39 页表格式&quot;">​</a></h1><div class="epigraph"><p>39 位虚拟地址切成三级 VPN，每级 9 位索引 512 项的页表页；叶 PTE 给出 PPN 与权限，硬件或软件走访这棵树。</p><footer>—— 据 The RISC-V Instruction Set Manual, Volume II: Privileged Architecture；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/riscv-compressed">上一课</a>只影响取指字节。<a href="/cs/multi-level-page-table">多级页表</a>已给树直觉，并点名 Sv39。缺口是 <strong>格式</strong>：PTE 位、<code>satp</code> 模式、与 x86-64 四/五级、ARM 多级对照时能指到具体字段。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Sv39：VA[38:12] 为 VPN，三级各 9 位，4 KiB 页。PTE：PPN、V/R/W/X/U/G/A/D 等。<code>satp</code> 存根 PPN 与 ASID、MODE=Sv39。缺口不是再画三级框图，而是这张<strong>位布局</strong>以及巨页（叶在上级标叶子）如何编码。</p><p>Sv48 再加一级，思想同。x86 <code>CR3</code>+4 级 9 位类似；ARM 用 TTBR 与不同块大小。本课以 Sv39 为钉。</p><h3 id="sv39-不是「39-位物理地址」" tabindex="-1">Sv39 不是「39 位物理地址」 <a class="header-anchor" href="#sv39-不是「39-位物理地址」" aria-label="Permalink to &quot;Sv39 不是「39 位物理地址」&quot;">​</a></h3><p>物理地址宽度由实现的 PPN 位决定，可以更宽。39 是虚拟地址canonical 空间（符号扩展到 64）。把 Sv39 当内存容量上限，HBM 容量故事会错。</p><p><span class="marginnote">RISC-V Privileged Spec 是权威。Patterson/Hennessy 教学分页。对照 <a href="/cs/ept-npt">EPT</a>：那是第二层翻译，Sv39 是客或宿主的第一层。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TLB 缺失：用 <code>satp.PPN</code> 为根，VPN[2] 索引，读 PTE，若非叶则 PPN 为下一级表，直到叶。故障：V=0 或权限不符 → 缺页/保护，写入 <code>scause</code>/<code>stval</code>。A/D 位由硬件或软件置，实现可选。</p>',11)),(a(),l(p,null,{default:s(()=>[d(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SATP%5B%22satp%20%E6%A0%B9%20PPN%22%5D%20--%3E%20L2%5B%22VPN%5B2%5D%20%E7%9B%AE%E5%BD%95%22%5D%0A%20%20L2%20--%3E%20L1%5B%22VPN%5B1%5D%22%5D%0A%20%20L1%20--%3E%20L0%5B%22VPN%5B0%5D%20%E5%8F%B6%20%E2%86%92%20PPN%22%5D%0A%20%20L0%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9AH%20%E6%89%A9%E5%B1%95%E5%86%8D%E5%8A%A0%E4%B8%80%E5%B1%82%E7%BF%BB%E8%AF%91%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与 <a href="/cs/dma-scatter-gather">DMA</a>：IOMMU 可用类似格式或另规格，不是 <code>satp</code> 本身。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>下一课虚拟化 H 扩展：G-stage 翻译把客物理再走一遍，类似 EPT。本课只钉单层 Sv39。fence.vma 刷新 TLB，与<a href="/cs/fence-instructions">内存 fence</a> 不同对象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Sv57 写完，不背每保留位。不讨论页表自己的 cache 着色。不进入 Windows 的 x86 格式对照作业。</p><p>后课默认：RISC-V Sv39 是三级 9 位索引的 PTE 树；<code>satp</code> 选模式。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VA 39 位，三级页表，4 KiB 叶。</li><li>PTE 含 PPN 与 RWX/U；<code>satp</code> 指向根。</li><li>虚拟化下一课加 G-stage。</li><li>出处：RISC-V Privileged Spec；Patterson and Hennessy, COD (RISC-V)。</li></ul>',8))])}const A=r(P,[["render",h]]);export{T as __pageData,A as default};
